  FROM last_ l JOIN tw t ON t.win = l.win AND t.psrk = l.psrk GROUP BY 1, 2),
frz AS (
  SELECT l.win, l.psrk, l.a_last, l.n, l.v_last, MIN(t.age) a_freeze, MIN_BY(t.v, t.age) v_freeze
  FROM last_ l JOIN chg c ON c.win = l.win AND c.psrk = l.psrk
  JOIN tw t ON t.win = l.win AND t.psrk = l.psrk AND t.age > c.a_changed
  GROUP BY 1, 2, 3, 4, 5),
